CREATE POLICY "Admins can delete backdrops" ON public.backdrops AS permissive FOR delete TO authenticated USING ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE ((staff_profiles.id = auth.uid()) AND (lower(staff_profiles.role) = 'admin'::text) AND (lower(staff_profiles.status) = 'active'::text)))));

CREATE POLICY "Admins can insert backdrops" ON public.backdrops AS permissive FOR insert TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE ((staff_profiles.id = auth.uid()) AND (lower(staff_profiles.role) = 'admin'::text) AND (lower(staff_profiles.status) = 'active'::text)))));

CREATE POLICY "Admins can view all bookings" ON public.bookings AS permissive FOR select TO authenticated USING ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE (staff_profiles.id = auth.uid()))));

CREATE POLICY "Staff can view gallery access requests" ON public.gallery_access_requests AS permissive FOR select TO authenticated USING ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE (staff_profiles.id = auth.uid()))));

CREATE POLICY "Admins can delete packages" ON public.packages AS permissive FOR delete TO authenticated USING ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE ((staff_profiles.id = auth.uid()) AND (staff_profiles.role = 'admin'::text) AND (staff_profiles.status = 'Active'::text)))));

CREATE POLICY "Admins can insert packages" ON public.packages AS permissive FOR insert TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE ((staff_profiles.id = auth.uid()) AND (staff_profiles.role = 'admin'::text) AND (staff_profiles.status = 'Active'::text)))));

CREATE POLICY "Admins can view all packages" ON public.packages AS permissive FOR select TO authenticated USING ((EXISTS ( SELECT 1
   FROM staff_profiles
  WHERE ((staff_profiles.id = auth.uid()) AND (staff_profiles.role = 'admin'::text) AND (staff_profiles.status = 'Active'::text)))));
